async function publishBatch4Adroit() {
  console.log('====================================================');
  console.log('  ADROIT REAL ESTATE SERVICES - 20 NEW BLOGS (BATCH 4)');
  console.log(`  Loaded ${adroitPosts.length} posts to publish`);
  console.log('====================================================\n');

  const headers = {
    'Content-Type': 'application/json',
    'x-admin-token': config.adminToken
  };

  let successCount = 0;

  for (let i = 0; i < adroitPosts.length; i++) {
    const post = adroitPosts[i];
    console.log(`▶ [${i + 1}/${adroitPosts.length}] Publishing: "${post.title}"`);
    console.log(`   Slug: ${post.slug}`);

    try {
      const res = await fetch(`${config.apiUrl}/admin/blogs`, {
        method: 'POST',
        headers,
        body: JSON.stringify({
          ...post,
          is_published: 1
        })
      });

      if (!res.ok) {
        const err = await res.text();
        throw new Error(`HTTP ${res.status}: ${err}`);
      }

      const data = await res.json().catch(() => ({}));
      console.log(`   ✓ Successfully published! ID: ${data.id || 'OK'}`);
      
      const verifyRes = await fetch(`${config.apiUrl}/blogs/${post.slug}`);
      if (verifyRes.ok) {
        console.log(`   ✓ Public API verified: ${config.baseUrl}/blog/${post.slug} (HTTP 200)\n`);
      }
      successCount++;
    } catch (err) {
      console.error(`   ❌ Failed to publish "${post.title}":`, err.message, '\n');
    }
  }

  // Update local blogs.json
  const blogsFile = path.join(__dirname, 'blogs.json');
  if (fs.existsSync(blogsFile)) {
    const blogs = JSON.parse(fs.readFileSync(blogsFile, 'utf-8'));
    adroitPosts.forEach(newPost => {
      const idx = blogs.findIndex(b => (b.slug || b.Slug) === newPost.slug);
      if (idx >= 0) {
        blogs[idx] = newPost;
      } else {
        blogs.push(newPost);
      }
    });
    fs.writeFileSync(blogsFile, JSON.stringify(blogs, null, 2), 'utf-8');
    console.log(`✓ Updated blogs.json (total: ${blogs.length} posts).`);
  }

  console.log(`\n🎉 Finished Adroit Batch 4: ${successCount}/${adroitPosts.length} posts successfully published!`);
}

publishBatch4Adroit().catch(err => {
  console.error('Fatal Error:', err);
  process.exit(1);
});
